def frames_for(face_name: str) -> list[bytes]:
    """Return a base face followed by every available numbered frame."""
    frames: list[bytes] = []
    base = BITMAPS.get(face_name)
    if base is not None:
        frames.append(base)

    for frame_number in range(1, 6):
        frame = BITMAPS.get(f"{face_name}_{frame_number}")
        if frame is not None:
            frames.append(frame)

    return frames
